INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (164, 1, 'PRIMARY KEY 란', '`id INT PRIMARY KEY` 로 만든 기본키 열에 대한 설명으로 알맞은 것은 무엇일까요?', '행 하나하나를 구분하는 이름표예요.', NULL, NULL, '[]', 'choice', '["중복이 허용되고 NULL 도 자유롭게 쓸 수 있다", "테이블에 여러 개의 기본키가 따로 있을 수 있다", "행을 구분하는 값이라 중복될 수 없고 NULL 도 될 수 없다 (`DESC` 에 `Null: NO`, `Key: PRI` 로 보인다). 열 두 개를 묶은 복합 키도 만들 수 있다", "기본키는 문자 열에만 쓸 수 있다"]', 2, '복합 키 `PRIMARY KEY (a, b)` 는 `(1,1)` 과 `(1,2)` 처럼 한쪽만 같은 것은 허용하고, 두 값이 모두 같으면 `ERROR 1062` 입니다.', NULL, NULL, NULL, NULL),
  (164, 2, 'DEFAULT 와 NULL', '`city VARCHAR(20) DEFAULT ''Seoul''` 인 열에 대해 `INSERT` 에서 `city` 를 생략했을 때와 `NULL` 을 직접 넣었을 때 값은 각각 무엇이 될까요?', '기본값은 "값을 안 줬을 때"만 쓰여요.', NULL, NULL, '[]', 'choice', '["둘 다 `Seoul` 이 된다", "생략하면 `Seoul` 이 채워지고, 명시적으로 `NULL` 을 넣으면 `NULL` 로 저장된다", "둘 다 `NULL` 이 된다", "생략하면 `NULL`, 명시적 `NULL` 이면 `Seoul` 이 된다"]', 1, '열을 아예 쓰지 않은 것과 NULL 을 넣은 것은 다릅니다. NULL 을 허용하지 않으려면 `NOT NULL` 도 함께 쓰세요.', NULL, NULL, NULL, NULL),
  (164, 3, 'UNIQUE 와 NULL', '`email VARCHAR(50) UNIQUE` 인 열에 같은 이메일을 두 번 넣으면 어떻게 될까요? 그리고 NULL 은 여러 번 넣을 수 있을까요?', 'UNIQUE 는 같은 값을 막지만, NULL 은 "값 없음"이에요.', NULL, NULL, '[]', 'choice', '["같은 이메일은 `ERROR 1062 Duplicate entry ... for key ''email''` 로 막히고, NULL 은 값이 없는 것이라 여러 번 넣을 수 있다", "같은 이메일도 허용되고 NULL 도 한 번만 가능하다", "같은 이메일은 막히고 NULL 도 한 번만 가능하다", "UNIQUE 는 아무것도 막지 못한다"]', 0, '이메일처럼 중복되면 안 되지만 비어 있을 수 있는 값에 알맞습니다. 비어 있으면 안 된다면 `NOT NULL` 도 함께 쓰세요.', NULL, NULL, NULL, NULL),
  (164, 4, '글자 수 초과', '`VARCHAR(5)` 열에 6글자 `''abcdef''` 를 넣으면 어떻게 될까요? 그리고 한글 3글자 `''한글한''` 은 `VARCHAR(3)` 에 들어갈까요?', '길이는 바이트가 아니라 글자 수로 세요.', NULL, NULL, '[]', 'choice', '["조용히 5글자로 잘려서 저장된다", "한글은 바이트 기준이라 `VARCHAR(3)` 에 들어가지 않는다", "항상 오류 없이 저장된다", "`ERROR 1406 Data too long for column` 으로 거부된다 (엄격 모드). 한글 3글자는 글자 수 기준이라 `VARCHAR(3)` 에 들어간다"]', 3, '엄격 모드가 꺼져 있으면 잘려 저장될 수 있어 위험합니다. 현재 서버가 엄격 모드인지는 `@@sql_mode` 로 확인하세요.', NULL, NULL, NULL, NULL),
  (164, 5, '자료형이 맞지 않을 때', '`INT` 열에 `''abc''` 와 `''7''` 을 넣으면 각각 어떻게 될까요?', '숫자 모양이면 변환되고, 아니면 오류예요.', NULL, NULL, '[]', 'choice', '["둘 다 거부된다", "둘 다 저장되고 `''abc''` 는 0 이 된다", "`''abc''` 는 `ERROR 1366 Incorrect integer value` 로 거부되고, 숫자 모양의 `''7''` 은 정수 7 로 변환되어 저장된다", "`''7''` 은 거부되고 `''abc''` 는 저장된다"]', 2, '숫자 모양의 문자열이 자동 변환되는 점은 편하지만 의도치 않은 비교 결과를 만들 수 있습니다. 가능하면 올바른 형으로 넣으세요.', NULL, NULL, NULL, NULL),
  (164, 6, 'DATE 의 형식과 검증', '`DATE` 열에 `''2026-02-30''` 을 넣으면 어떻게 될까요?', '달력에 없는 날짜예요.', NULL, NULL, '[]', 'choice', '["2026-03-02 로 자동 보정되어 저장된다", "`ERROR 1292 Incorrect date value` 로 거부된다. `DATE` 는 `YYYY-MM-DD` 형식의 실제로 있는 날짜만 받는다", "0000-00-00 으로 저장된다", "아무 오류 없이 문자열 그대로 저장된다"]', 1, '시각까지 필요하면 `DATETIME` 을 씁니다. 현재 시각의 기본값은 `DEFAULT CURRENT_TIMESTAMP` 로 줄 수 있어요.', NULL, NULL, NULL, NULL),
  (164, 7, 'DECIMAL(5,2) 읽기', '`DECIMAL(5,2)` 열에 `1234.5` 와 `1.239` 를 넣으면 각각 어떻게 될까요?', '전체 5자리 중 소수 2자리라서 정수부는 3자리까지예요.', NULL, NULL, '[]', 'choice', '["`1234.5` 는 정수부가 3자리를 넘어 `ERROR 1264 Out of range` 로 거부되고, `1.239` 는 소수 2자리로 반올림되어 `1.24` 로 저장된다 (오류 아님)", "`1234.5` 는 저장되고 `1.239` 는 거부된다", "둘 다 저장된다", "둘 다 거부된다"]', 0, '`DECIMAL(전체 자릿수, 소수 자릿수)` 입니다. 소수 자릿수가 넘치면 오류가 아니라 반올림되므로 의도한 자릿수를 정확히 정하세요.', NULL, NULL, NULL, NULL),
  (164, 8, 'DECIMAL 과 FLOAT', '금액처럼 소수까지 정확해야 하는 값은 `DECIMAL` 과 `FLOAT` 중 무엇이 알맞을까요?', '부동소수점은 근사값이에요.', NULL, NULL, '[]', 'choice', '["`FLOAT` 가 더 정확하다", "둘은 오차가 똑같다", "`DECIMAL` 은 정수만 저장한다", "`DECIMAL` 이 알맞다. `FLOAT` 는 근사값이라 `0.1 + 0.2 = 0.3` 이 참이 되지 않고 합계가 `0.3000000045` 처럼 오차가 생길 수 있다"]', 3, '소수 리터럴 `0.1+0.2=0.3` 은 `DECIMAL` 계산으로 참이지만 `0.1e0+0.2e0=0.3e0` (`DOUBLE`)는 거짓입니다. 돈은 항상 `DECIMAL` 로 저장하세요.', NULL, NULL, NULL, NULL),
  (164, 9, '글자 수와 바이트 수', '`utf8mb4` 에서 `CHAR_LENGTH(''한글'')` 과 `LENGTH(''한글'')` 은 각각 얼마일까요?', '하나는 글자를 세고 하나는 바이트를 세요.', NULL, NULL, '[]', 'choice', '["둘 다 2 이다", "둘 다 6 이다", "`CHAR_LENGTH` 는 2(글자 수), `LENGTH` 는 6(바이트 수, 한글 한 글자가 3바이트)이다", "`CHAR_LENGTH` 는 6, `LENGTH` 는 2 이다"]', 2, '`VARCHAR(n)` 의 `n` 은 글자 수입니다. 이모지처럼 4바이트 글자도 `utf8mb4` 에서는 저장되지만 `utf8`(3바이트)에서는 저장되지 않아요.', NULL, NULL, NULL, NULL),
  (164, 10, '외래 키의 두 오류', '`orders.customer_id` 가 `customers(id)` 를 참조하는 외래 키일 때 `customers` 에 없는 `999` 를 넣을 때와, 주문이 있는 고객을 삭제할 때 오류는 각각 무엇일까요?', '자식이 부모를 찾지 못할 때와 부모를 지우려는데 자식이 있을 때예요.', NULL, NULL, '[]', 'choice', '["둘 다 `ERROR 1062` 이다", "없는 부모를 가리키면 `ERROR 1452 Cannot add or update a child row`, 자식이 있는 부모를 지우거나 그 테이블을 `DROP` 하면 `ERROR 1451 Cannot delete or update a parent row`", "둘 다 오류 없이 성공한다", "삭제는 항상 성공하고 입력만 오류가 난다"]', 1, '외래 키는 데이터가 서로 어긋나지 않게 지켜 줍니다. 부모를 먼저 만들고 자식을 나중에 넣고, 삭제는 자식을 먼저 지우세요.', NULL, NULL, NULL, NULL),
  (164, 11, 'CASCADE 와 SET NULL', '외래 키에 `ON DELETE CASCADE` 와 `ON DELETE SET NULL` 을 쓰면 부모를 삭제할 때 자식은 각각 어떻게 될까요?', '하나는 따라 지우고, 하나는 연결만 끊어요.', NULL, NULL, '[]', 'choice', '["`CASCADE` 는 자식 행도 함께 삭제되고, `SET NULL` 은 자식 행은 남고 외래 키 열이 NULL 로 바뀐다 (그 열이 NULL 을 허용해야 한다)", "둘 다 삭제가 거부된다", "`CASCADE` 는 NULL 로, `SET NULL` 은 함께 삭제한다", "둘 다 아무 일도 일어나지 않는다"]', 0, '`CASCADE` 는 실수로 지우면 연쇄로 사라지니 조심하세요. 지우면 안 되는 이력 데이터에는 기본(`RESTRICT`)이 안전합니다.', NULL, NULL, NULL, NULL),
  (164, 12, 'ALTER 로 열 추가·삭제', '이미 데이터가 있는 테이블에 `ALTER TABLE a ADD COLUMN age INT` 를 하면 기존 행의 `age` 는 어떻게 될까요? 그리고 `DROP COLUMN` 은 어떤 결과일까요?', '새 열의 값은 기본값(없으면 NULL)으로 채워져요.', NULL, NULL, '[]', 'choice', '["기존 행이 모두 삭제된다", "`ADD COLUMN` 은 빈 테이블에서만 가능하다", "`DROP COLUMN` 은 열을 숨기기만 하고 데이터는 남는다", "기존 행의 `age` 는 NULL (기본값을 지정했으면 그 값)이 된다. `DROP COLUMN` 은 그 열이 사라지며 그 열의 데이터도 함께 사라진다"]', 3, '`ALTER` 는 DDL 이라 `ROLLBACK` 이 안 되니 실행 전에 백업하세요. `NOT NULL DEFAULT ''new''` 로 추가하면 기존 행도 `new` 로 채워집니다.', NULL, NULL, NULL, NULL),
  (164, 13, '열 길이를 줄일 때', '기존 데이터가 들어 있는 `VARCHAR(100)` 열을 `ALTER TABLE ... MODIFY name VARCHAR(0)` 처럼 기존 값보다 짧게 바꾸려고 하면 어떻게 될까요?', '이미 들어 있는 값이 새 길이에 맞지 않아요.', NULL, NULL, '[]', 'choice', '["기존 데이터가 조용히 잘려 저장된다", "항상 성공한다", "기존 값이 새 길이에 맞지 않으면 엄격 모드에서 `ERROR 1406 Data too long` 으로 거부된다. 늘리는 변경은 보통 안전하다", "테이블이 삭제된다"]', 2, '줄이기 전에 `SELECT MAX(CHAR_LENGTH(name))` 로 가장 긴 값을 확인하세요. 늘리는 `MODIFY name VARCHAR(100)` 은 데이터에 영향이 없어요.', NULL, NULL, NULL, NULL),
  (164, 14, 'IF NOT EXISTS', '이미 있는 테이블에 `CREATE TABLE a (...)` 와 `CREATE TABLE IF NOT EXISTS a (...)` 를 실행하면 각각 어떻게 될까요? 없는 테이블의 `DROP TABLE` 과 `DROP TABLE IF EXISTS` 는 어떨까요?', 'IF 가 붙으면 이미 있거나 없을 때도 오류 없이 넘어가요.', NULL, NULL, '[]', 'choice', '["네 가지 모두 오류 없이 성공한다", "`CREATE TABLE` 은 `ERROR 1050 already exists`, `IF NOT EXISTS` 는 오류 없이 경고만 남긴다. `DROP TABLE` 은 `ERROR 1051 Unknown table`, `IF EXISTS` 는 오류가 없다", "네 가지 모두 오류가 난다", "`IF` 가 붙으면 항상 테이블을 새로 만든다"]', 1, '스크립트를 여러 번 실행해도 안전하게 만들려면 `IF NOT EXISTS`, `IF EXISTS` 를 쓰세요. 단, 테이블의 구조까지 맞춰 주지는 않으니 주의해요.', NULL, NULL, NULL, NULL),
  (164, 15, '테이블 만들기', '새 **테이블을 만드는** 구문의 대상 키워드를 채우세요.', '"표"를 뜻하는 영어 단어예요.', NULL, NULL, '[]', 'fill', '["TABLE", "SHEET", "ENTITY", "SCHEMA"]', NULL, '열 이름, 자료형, 제약을 괄호 안에 쉼표로 나열합니다. 만든 뒤 `DESC` 로 확인하세요.', '[0]', 'CREATE {0} customers (id INT PRIMARY KEY)', NULL, NULL),
  (164, 16, '기본키 지정', '`id` 열을 **행을 구분하는 기본키**로 만드는 키워드를 채우세요.', '"으뜸의"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["PRIMARY", "MAIN", "FIRST", "UNIQUE"]', NULL, '`PRIMARY KEY` 는 중복과 NULL 을 모두 막습니다. 한 테이블에 하나만 둘 수 있어요.', '[0]', 'id INT {0} KEY AUTO_INCREMENT', NULL, NULL),
  (164, 17, '비어 있으면 안 되는 열', '`name` 열이 **NULL 이 될 수 없도록** 하는 키워드를 채우세요.', '"~이 아닌"이라는 뜻의 짧은 영어 단어예요.', NULL, NULL, '[]', 'fill', '["NOT", "NO", "NON", "DENY"]', NULL, '`NOT NULL` 인데 값 없이 `INSERT` 하면 기본값이 없을 때 `ERROR 1364` 가 납니다.', '[0]', 'name VARCHAR(30) {0} NULL', NULL, NULL),
  (164, 18, '기본값 정하기', '`city` 를 생략했을 때 **`Seoul` 이 채워지게** 하는 키워드를 채우세요.', '"기본값"을 뜻하는 영어 단어예요.', NULL, NULL, '[]', 'fill', '["DEFAULT", "INIT", "FILL", "BASE"]', NULL, '값을 생략했을 때만 쓰입니다. 명시적으로 `NULL` 을 넣으면 `NULL` 이 저장돼요.', '[0]', 'city VARCHAR(20) {0} ''Seoul''', NULL, NULL),
  (164, 19, '중복 막기', '`email` 값이 **중복되지 않게** 하는 키워드를 채우세요.', '"유일한"이라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["UNIQUE", "ONLY", "SINGLE", "DISTINCT"]', NULL, 'NULL 은 여러 번 넣을 수 있습니다. 중복 시 `ERROR 1062` 가 납니다.', '[0]', 'email VARCHAR(50) {0}', NULL, NULL),
  (164, 20, '생성 시각 자동 기록', '행이 만들어진 **현재 시각이 자동으로 들어가게** 하는 기본값을 채우세요.', '"현재의 시각 도장"을 뜻하는 이름이에요.', NULL, NULL, '[]', 'fill', '["CURRENT_TIMESTAMP", "NOW", "TODAY", "CLOCK"]', NULL, '`INSERT` 에서 `created_at` 을 생략하면 그 순간의 시각이 채워집니다. `DESC` 의 Default 에 `current_timestamp()` 로 보여요.', '[0]', 'created_at DATETIME DEFAULT {0}', NULL, NULL),
  (164, 21, '정확한 소수 자료형', '금액처럼 **오차 없이 소수를 저장하는** 자료형을 채우세요.', '"십진수"를 뜻하는 영어 단어예요.', NULL, NULL, '[]', 'fill', '["DECIMAL", "FLOAT", "REAL", "NUMBER"]', NULL, '`(10,2)` 는 전체 10자리, 소수 2자리입니다. `FLOAT` 는 근사값이라 합계에 오차가 생겨요.', '[0]', 'price {0}(10,2)', NULL, NULL),
  (164, 22, '다른 테이블 가리키기', '`customer_id` 가 `customers(id)` 를 **참조**하도록 하는 키워드를 채우세요.', '"참조하다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["REFERENCES", "LINKS", "POINTS", "TO"]', NULL, '참조되는 쪽(`customers`)이 먼저 있어야 하고, 자식이 있으면 부모를 지울 수 없습니다.', '[0]', 'FOREIGN KEY (customer_id) {0} customers(id)', NULL, NULL),
  (164, 23, '부모를 지울 때 자식도', '부모를 삭제하면 **자식 행도 함께 삭제되게** 하는 값을 채우세요.', '"연쇄 반응"을 뜻하는 영어 단어예요.', NULL, NULL, '[]', 'fill', '["CASCADE", "CLEAN", "FOLLOW", "REMOVE"]', NULL, '연쇄로 데이터가 사라지니 신중히 쓰세요. 연결만 끊으려면 `SET NULL` 입니다.', '[0]', 'FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE {0}', NULL, NULL),
  (164, 24, '열 추가하기', '기존 테이블에 **새 열을 더하는** `ALTER TABLE` 의 동작 키워드를 채우세요.', '"더하다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["ADD", "APPEND", "NEW", "PUT"]', NULL, '기존 행의 새 열은 NULL(또는 `DEFAULT` 값)로 채워집니다. `ALTER` 는 `ROLLBACK` 이 안 돼요.', '[0]', 'ALTER TABLE a {0} COLUMN age INT', NULL, NULL),
  (164, 25, '열 이름 바꾸기', '열 `age` 의 **이름을 `years` 로 바꾸는** 동작 키워드를 채우세요.', '"이름을 바꾸다"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["RENAME", "CHANGE-NAME", "MOVE", "ALIAS"]', NULL, '그 열을 쓰는 쿼리와 앱 코드도 함께 고쳐야 합니다. 이름 변경은 데이터를 건드리지 않아요.', '[0]', 'ALTER TABLE a {0} COLUMN age TO years', NULL, NULL),
  (164, 26, '테이블 설계하고 만들어 확인하기', '필요한 값을 정해 테이블을 만들고 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '설계 → 만들기 → 구조 확인 → 시험 입력 순서예요.', NULL, NULL, '[]', 'order', '["어떤 값이 필요한지, 중복·NULL·기본값 규칙을 정한다", "`CREATE TABLE` 로 기본키, `NOT NULL`, `DEFAULT`, `UNIQUE` 를 정해 만든다", "`DESC` 로 `Null`, `Key`, `Default` 가 의도대로인지 본다", "`INSERT` 로 정상 값과 잘못된 값을 넣어 보며 오류가 의도대로 나는지 시험한다"]', NULL, '제약은 나중에 추가하기 어렵거나 기존 데이터와 충돌할 수 있으니 처음부터 정하는 것이 좋습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (164, 27, '외래 키 오류 풀기', '`ERROR 1452` 또는 `ERROR 1451` 이 났을 때의 해결 순서입니다. 순서에 맞게 놓아 보세요.', '오류 읽기 → 부모 확인 → 순서 바로잡기 → 다시 실행 순서예요.', NULL, NULL, '[]', 'order', '["오류 번호와 메시지에서 어느 테이블이 자식이고 어느 쪽이 부모인지 읽는다 (1452 는 부모 없음, 1451 은 자식이 남음)", "`SELECT` 로 부모 행이 있는지, 자식 행이 남아 있는지 확인한다", "부모를 먼저 `INSERT` 하거나, 자식을 먼저 `DELETE` 해서 순서를 바로잡는다", "원래 명령을 다시 실행해 성공하는지 확인한다"]', NULL, '삭제할 자식이 많다면 `ON DELETE CASCADE` 를 고려할 수 있지만 의도치 않은 연쇄 삭제를 조심하세요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (164, 28, '운영 중인 테이블에 열 추가하기', '데이터가 있는 테이블에 열을 안전하게 추가하는 순서입니다. 순서에 맞게 놓아 보세요.', '백업 → 추가 → 구조 확인 → 값 확인 순서예요.', NULL, NULL, '[]', 'order', '["`mysqldump` 같은 도구로 백업한다", "`ALTER TABLE ... ADD COLUMN ... NOT NULL DEFAULT ''값''` 으로 기본값과 함께 열을 추가한다", "`DESC` 로 새 열의 자료형과 기본값을 확인한다", "`SELECT` 로 기존 행에도 기본값이 채워졌는지 확인한다"]', NULL, '`ALTER` 는 되돌릴 수 없고 큰 테이블에서는 오래 걸릴 수 있습니다. 사용량이 적은 시간에 실행하세요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (164, 29, 'Data too long 오류 풀기', '`ERROR 1406 Data too long for column` 이 났을 때의 해결 순서입니다. 순서에 맞게 놓아 보세요.', '오류 읽기 → 열 길이 확인 → 조정 → 다시 입력 순서예요.', NULL, NULL, '[]', 'order', '["오류 메시지에서 어느 열과 어느 행인지 읽는다", "`DESC` 나 `SHOW CREATE TABLE` 로 그 열의 길이를 확인한다", "값이 정말 그만큼 길어야 한다면 `ALTER TABLE ... MODIFY ... VARCHAR(100)` 으로 늘리고, 아니면 입력값을 줄인다", "다시 `INSERT` 해서 성공하는지 확인한다"]', NULL, '엄격 모드가 아니면 값이 조용히 잘리므로 오류가 나는 지금이 오히려 안전한 상황입니다.', '[0, 1, 2, 3]', NULL, NULL, NULL);
